contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val1, uint _val2) public payable {
        require(true);

        c.SetMinSum(_val1); if (__ESBMC_reverted()) return;
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        uint before2 = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(_val2); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.MinSum() == before2);
    }

    receive() external payable {}
}

