pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 _val1, uint256 _val2) internal {
        vm.assume(true);
        try c.SetMinSum(_val1) {} catch { return; }
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 before2;
        try c.MinSum() returns (uint256 __r) { before2 = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(_val2) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.MinSum() == before2);
    }

    function testFuzz_run(uint256 _val1, uint256 _val2) public {
        _run(_val1, _val2);
    }

    receive() external payable {}
}
